{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#F6F1EA;--card:#FFFFFF;--accent:#7B5E3B;--muted:#8B7F72;--accent-2:#C9A66B;--ink:#2E2A25}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--ink);background:var(--bg)}
    header{background:linear-gradient(180deg,rgba(123,94,59,0.08),transparent);padding:28px 20px;border-bottom:1px solid rgba(46,42,37,0.06)}
    .wrap{max-width:980px;margin:0 auto}
    nav{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
    nav a{color:var(--ink);text-decoration:none;font-weight:600}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:36px 20px}
    .hero h1{margin:0;font-size:26px;color:var(--accent)}
    .hero p.lead{margin:0;color:var(--muted)}
    .cards{display:grid;grid-template-columns:1fr 360px;gap:20px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(46,42,37,0.06)}
    .profile{display:flex;gap:16px;align-items:center}
    .avatar{width:88px;height:88px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    h2{margin:0 0 8px 0}
    ul{margin:8px 0;padding-left:18px}
    .muted{color:var(--muted);font-size:15px}
    .small{font-size:13px;color:var(--muted)}

    /* Session Planner + Wizard */
    .widget{display:flex;flex-direction:column;gap:12px}
    .field{display:flex;flex-direction:column;gap:6px}
    label{font-weight:600;font-size:13px}
    input[type=text],select,textarea{padding:10px;border-radius:8px;border:1px solid rgba(46,42,37,0.08);font-size:14px}
    button.primary{background:var(--accent);color:white;border:none;padding:10px 14px;border-radius:8px;cursor:pointer}
    button.secondary{background:transparent;border:1px solid rgba(46,42,37,0.08);padding:8px 12px;border-radius:8px;cursor:pointer}
    .output{white-space:pre-wrap;background:#FBF8F5;padding:12px;border-radius:8px;border:1px dashed rgba(46,42,37,0.06);font-size:14px}
    .legal{font-size:13px;color:var(--muted);margin-top:12px}
    footer{padding:20px;text-align:center;color:var(--muted);font-size:13px}

    /* responsive */
    @media(min-width:920px){.hero{grid-template-columns:1fr 320px}.cards{grid-template-columns:1fr 360px}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Areas</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Start</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero">
      <div>
        <h1>Therapy that helps you arrange the next chapter, not rewrite the plot</h1>
        <p class="lead">I’m a licensed clinician offering a membership-based practice for steady, practical work on life’s patterns and transitions. Sessions feel purposeful, private, and paced to what you can carry.</p>
      </div>
      <aside class="card">
        <div class="profile">
          <div class="avatar">LC</div>
          <div>
            <div style="font-weight:700">Licensed Clinician</div>
            <div class="small">Serving adults in {{CITY}}, {{STATE}} • Telehealth available</div>
            <div style="margin-top:8px"><a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
          </div>
        </div>
      </aside>
    </section>

    <section class="cards" style="margin-top:8px">
      <div>
        <article class="card">
          <h2>About my work</h2>
          <p class="muted">My practice centers on calm, focused conversations that move toward clearer choices, more reliable coping, and improved day-to-day rhythm. I combine evidence-informed approaches with attention to personal story and what’s possible in your life now.</p>
          <h3 style="margin-top:16px">Who I typically work with</h3>
          <ul>
            <li>Adults navigating transitions: work changes, relationship shifts, parenting concerns</li>
            <li>People with persistent anxiety, low mood, or patterns that interfere with goals</li>
            <li>Those wanting regular support through a membership rather than sporadic blocks</li>
          </ul>
          <h3 style="margin-top:12px">How the membership works</h3>
          <p class="muted">Memberships are an ongoing model: a regular cadence of sessions, access to structured brief courses, and priority scheduling. Pricing is presented in transparent options—no surprise packages. If you prefer short series, I offer focused multi-session programs for specific goals.</p>
        </article>

        <article class="card" style="margin-top:14px">
          <h2>Confidentiality & boundaries</h2>
          <p class="muted">Conversations are confidential within legal limits. I will explain confidentiality, record-keeping, and limits to confidentiality at our first meeting. I do not provide emergency services; if you are in immediate danger or a life-threatening emergency, please call local emergency services or your crisis line.</p>
          <p class="small" style="margin-top:10px"><strong>Scope:</strong> My work is therapy for adults. I do not provide forensic evaluations or on-call crisis management. If a different service is more appropriate I will help connect you with resources.</p>
        </article>

      </div>

      <aside>
        <div class="card">
          <h2>Quick Session Planner</h2>
          <p class="small">Build a short plan for what to address in your first few sessions and copy a simple summary to bring to the consult.</p>
          <div class="widget" id="planner">
            <div class="field"><label for="goal">Primary goal for therapy</label><input id="goal" type="text" placeholder="e.g., manage work anxiety, repair relationship patterns"></div>
            <div class="field"><label for="frequency">Preferred rhythm</label><select id="frequency"><option>Weekly</option><option>Biweekly</option><option>Monthly</option></select></div>
            <div class="field"><label for="length">Session length</label><select id="length"><option>50 minutes</option><option>75 minutes</option></select></div>
            <div class="field"><label for="priority">Top 3 things to address (comma separated)</label><input id="priority" type="text" placeholder="e.g., sleep, boundaries, decision-making"></div>
            <div style="display:flex;gap:8px;margin-top:6px"><button class="primary" id="buildPlan">Create plan</button><button class="secondary" id="clearPlan">Clear</button></div>
            <div class="output" id="planOutput">Your plan will appear here.</div>
            <div style="display:flex;gap:8px;margin-top:8px"><button class="secondary" id="copyPlan">Copy summary</button></div>
          </div>
        </div>

        <div class="card" style="margin-top:14px">
          <h2>Self-Screening: Questions for your first visit</h2>
          <p class="small">A brief intake exercise to help you notice patterns and bring focused questions to the consultation. This is non-diagnostic and intended to guide conversation.</p>
          <form id="wizard">
            <div class="field"><label>How often do symptoms interfere with daily routines?</label>
              <select name="interfere"><option>Slightly</option><option>Sometimes</option><option>Often</option><option>Daily</option></select>
            </div>
            <div class="field"><label>Stressors: Which are present now? (select all that apply)</label>
              <div style="display:flex;flex-direction:column;gap:6px;margin-top:6px">
                <label><input type="checkbox" name="stress" value="Work"> Work pressure</label>
                <label><input type="checkbox" name="stress" value="Relationships"> Relationships</label>
                <label><input type="checkbox" name="stress" value="Health"> Health concerns</label>
                <label><input type="checkbox" name="stress" value="Sleep"> Sleep problems</label>
                <label><input type="checkbox" name="stress" value="Transitions"> Life transitions</label>
              </div>
            </div>
            <div style="display:flex;gap:8px;margin-top:10px"><button class="primary" id="generateQuestions">Generate questions</button><button class="secondary" id="resetWizard">Reset</button></div>
          </form>
          <div class="output" id="wizardOutput">Suggested prompts will appear here.</div>
        </div>

      </aside>
    </section>

    <div class="legal">This site is for informational purposes and does not create a therapeutic relationship. If you are in crisis, call local emergency services or a crisis line. Contact: {{PHONE}} • {{EMAIL}}</div>
  </main>

  <footer>
    <div class="wrap">&copy; <span id="year"></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    // Session Planner
    const buildBtn = document.getElementById('buildPlan');
    const clearBtn = document.getElementById('clearPlan');
    const copyBtn = document.getElementById('copyPlan');
    const out = document.getElementById('planOutput');

    function buildSummary(){
      const goal = document.getElementById('goal').value.trim();
      const freq = document.getElementById('frequency').value;
      const length = document.getElementById('length').value;
      const priority = document.getElementById('priority').value.trim();
      let lines = [];
      lines.push('Planned focus for consultation: ' + (goal || '(no goal entered)'));
      lines.push('Preferred session rhythm: ' + freq + ' • ' + length);
      if(priority) lines.push('Top focus areas: ' + priority);
      lines.push('Prepared by visitor on ' + new Date().toLocaleDateString());
      return lines.join('\n');
    }

    buildBtn.addEventListener('click', function(e){
      e.preventDefault();
      out.textContent = buildSummary();
    });
    clearBtn.addEventListener('click', function(){
      document.getElementById('goal').value='';
      document.getElementById('priority').value='';
      out.textContent='Your plan will appear here.';
    });
    copyBtn.addEventListener('click', function(){
      const text = out.textContent;
      if(!text || text === 'Your plan will appear here.') return;
      navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
        copyBtn.textContent = 'Copied';
        setTimeout(()=>copyBtn.textContent='Copy summary',1200);
      }).catch(()=>{
        alert('Copy failed; select the text and copy manually.');
      });
    });

    // Self-screening wizard
    const wizard = document.getElementById('wizard');
    const genBtn = document.getElementById('generateQuestions');
    const resetWizard = document.getElementById('resetWizard');
    const wizOut = document.getElementById('wizardOutput');

    genBtn.addEventListener('click', function(e){
      e.preventDefault();
      const interfere = wizard.elements['interfere'].value;
      const checks = Array.from(wizard.querySelectorAll('input[name="stress"]:checked')).map(n=>n.value);
      let prompts = [];
      prompts.push('Describe when these difficulties began and any clear triggers.');
      prompts.push('How do these difficulties affect daily routines or relationships? (e.g., sleep, work, mood)');
      if(interfere === 'Often' || interfere === 'Daily') prompts.push('Have you noticed any coping strategies that help, even briefly?');
      if(checks.length) prompts.push('Current stress areas: ' + checks.join(', '));
      prompts.push('What would you hope is different in 3 months if things went better?');
      wizOut.textContent = prompts.join('\n\n');
    });
    resetWizard.addEventListener('click', function(e){
      e.preventDefault();
      wizard.reset();
      wizOut.textContent = 'Suggested prompts will appear here.';
    });
  </script>
</body>
</html>"} 
