  <script>
    // Planner in this page
    document.getElementById('makePlan').addEventListener('click', function(){
      const one = document.getElementById('one').value.trim();
      const skill = document.getElementById('skill').value;
      const rhythm = document.getElementById('rhythm').value;
      const out = document.getElementById('planNote');
      const summary = [
        'Focused aim: ' + (one || '(not specified)'),
        'Primary skill target: ' + skill,
        'Suggested rhythm: ' + rhythm,
        'Prepared: ' + new Date().toLocaleString()
      ].join('\n');
      out.textContent = summary;
    });
    document.getElementById('resetPlan').addEventListener('click', function(){
      document.getElementById('one').value='';
      document.getElementById('planNote').textContent='Plan will appear here.';
    });
    document.getElementById('copyNote').addEventListener('click', function(){
      const text = document.getElementById('planNote').textContent;
      if(!text || text === 'Plan will appear here.') return;
      navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
        this.textContent = 'Copied';
        setTimeout(()=>this.textContent='Copy',1200);
      });
    });

    // Self-screening topics
    document.getElementById('scoreIt').addEventListener('click', function(){
      const v1 = +document.getElementById('r1').value;
