      const arr = [ ['Work stress',v1], ['Sleep',v2], ['Relationships',v3] ];
      arr.sort((a,b)=>b[1]-a[1]);
      const top = arr.slice(0,3).map(a=>a[0]);
      document.getElementById('topics').textContent = 'Top topics to discuss:\n1. ' + top[0] + '\n2. ' + top[1] + '\n3. ' + top[2];
